import React, { useState, useEffect } from "react";
import Dashboard from './Dashboard';
import DataTable from 'react-data-table-component';
import { FaRegArrowAltCircleLeft } from "react-icons/fa";
import { useLocation } from 'react-router-dom';
import { RiDeleteBin6Line } from "react-icons/ri";
import { makeApiRequest } from "../axiosService/ApiCall"
import { ToastContainer, toast } from "react-toastify";
import { Modal, Button } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom'
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { decryptData } from "../Auth/SecurityCrypto";
import axios from "axios";

function KYCform() {
    const [isVisible, setIsVisible] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const [selectedRow, setSelectedRow] = useState(null);
    const [content, setContent] = useState('');
    const location = useLocation();
    const [kycForm, setKycForm] = useState(location.state?.kycForm || {});
    const [verticalData, setVerticalData] = useState([])
    const [verticalData2, setVerticalData2] = useState([])
    const [verticalData3, setVerticalData3] = useState([])
    const Navigate = useNavigate()

    const columns = [
        {
            name: 'User Details',
            selector: row => row.field,
            sortable: false,
            width: '500px',
        },
        {
            name: '',
            selector: row => row.value,
            sortable: false,
            width: '250px',
        }
    ];

    const columns1 = [
        {
            name: 'Phone.No & Address',
            selector: row => row.field,
            sortable: false,
            width: '500px',
        },
        {
            name: '',
            selector: row => row.value,
            sortable: false,
            width: '250px',
        },
    ];

    const columns2 = [
        {
            name: 'KYC Status',
            selector: row => row.field,
            sortable: false,
            width: '500px',
        },
        {
            name: '',
            selector: row => row.value,
            sortable: false,
            width: '250px',
        }
    ];

    useEffect(() => {
        if (!kycForm) return;
        setVerticalData([
            { id: `1`, field: 'Citizenship', value: kycForm.KYC_document?.[0]?.citizenship || "NA" },
            { id: `2`, field: 'Country', value: kycForm.KYC_document?.[0]?.country || "NA" },
            { id: `3`, field: 'Are you Liable in US', value: kycForm.KYC_document?.[0]?.US_resident == true ? "YES" : "NO" },
            { id: `4`, field: 'Occupation', value: kycForm.KYC_document?.[0]?.occupation || "NA" },
            { id: `5`, field: 'Tax_ID', value: kycForm.KYC_document?.[0]?.tax_ID || "NA" },
            { id: `6`, field: 'Date of Birth', value: kycForm.birth_information?.[0]?.birthday || "NA" },
            { id: `7`, field: 'Country of Birth', value: kycForm.birth_information?.[0]?.birth_place || "NA" },
            { id: `8`, field: 'Gender', value: kycForm.birth_information?.[0]?.gender || "NA" },

        ].flat())

        setVerticalData2([
            { id: `1`, field: 'Phone Number', value: kycForm.phone_number?.[0]?.number || "NA" },
            { id: `2`, field: 'Address Line 1', value: kycForm.current_Address?.[0]?.address_1 || "NA" },
            { id: `3`, field: 'Address Line 2', value: kycForm.current_Address?.[0]?.address_2 || "NA" },
            { id: `4`, field: 'Resident Country', value: kycForm.current_Address?.[0]?.resident_country || "NA" },
            { id: `5`, field: 'Provinces', value: kycForm.current_Address?.[0]?.state || "NA" },
            { id: `6`, field: 'City', value: kycForm.current_Address?.[0]?.city || "NA" },
            { id: `7`, field: 'Zip Code', value: kycForm.current_Address?.[0]?.zip_code || "NA" },

        ].flat())

        setVerticalData3([
            { id: `1`, field: 'KYC SDK Status', value: kycForm.sdk_verification?.sdkStatus || "Not Verified" },
            { id: `1`, field: 'KYC Status', value: kycForm.sdk_verification?.reviewRejectType == "FINAL" ? "Rejected" : kycForm.sdk_verification?.reviewRejectType == "RETRY" ? "Pending" : kycForm.sdk_verification?.reviewRejectType || "Not Verified" },
            { id: `2`, field: 'Applicant-ID', value: kycForm.sdk_verification?.applicantID || "Not Verified" },
            { id: `3`, field: 'Applicant User ID', value: kycForm.sdk_verification?.externalUserID || "Not Verified" },

        ].flat())

    }, [kycForm]);



    const handleDeleteClick = async () => {
        try {
            setSelectedRow(kycForm._id);
            let datas = {
                FormId: kycForm._id,
                type: "KycDelete"
            }
            let params = {
                url: `getFormDetails`,
                method: 'POST',
                data: datas,

            };
            // console.log('params', params)
            const kycdeletedata = await makeApiRequest(params)

                .then((response) => {
                    setContent(response.message);
                })
                .catch((error) => {
                    console.log('error', error);
                })
            //    console.log("kycdeletedata", kycdeletedata) 

            setShowModal(true);
        } catch (error) {
            console.log(error)
        }
    };

    const confirmDelete = async () => {
        if (selectedRow) {

            await handleKYCDelete(selectedRow);
        }
        setShowModal(false);
    };

    const handleClose = () => setShowModal(false);

    const handleKYCDelete = async () => {

        const address = await axios.get("https://api.ipify.org/?format=json");

        const lastloginIpAddress = address.data.ip;

        let datas = {
            FormId: selectedRow,
            type: "KycDelete",
            ip: lastloginIpAddress
        }
        let params = {
            url: `formsDelete`,
            method: 'POST',
            data: datas,

        };
        // console.log('params', params)
        const kycdecryptres = await makeApiRequest(params);
        // console.log("kycdecryptres", kycdecryptres);   
        const kycdecryptedRes = decryptData(kycdecryptres.data);
        // console.log("kycdecryptedRes", kycdecryptedRes);     
        try {
            toast.success(kycdecryptedRes.message);
            setTimeout(() => {
                Navigate("/dashboard/user-list")
            }, 2000)
        } catch (err) {
            console.log('error', err);
            toast.error("Something went wrong")
        }
        // .then((response) => {
        //     console.log('response', response)

        // })
        // .catch((error) => {

        // })
    };


    const toggleVisibility = () => {
        if (window.pageYOffset > 300) {
            setIsVisible(true);
        } else {
            setIsVisible(false);
        }
    };

    const scrollToTop = () => {
        window.scrollTo({
            top: 0,
            behavior: "smooth",
        });
    };

    const handleKYC = async () => {
        try {
            let params = {
                url: "get_KYC_Form",
                method: "post",
                data: { id: kycForm.user_id },
            };
            const response = await makeApiRequest(params);
            if (response.status === true) {
                const kycForms = response.resp;
                if (kycForms) {
                    setKycForm(kycForms);
                } else {
                    toast.error("This user has not yet uploaded their KYC.");
                }
            } else {
                toast.error("KYC form not found for this user.");
            }
        } catch (error) {
            console.log(error)
            toast.error("Error fetching KYC form.");
        }
    };

    useEffect(() => {
        window.addEventListener("scroll", toggleVisibility);
        handleKYC();
        return () => {
            window.removeEventListener("scroll", toggleVisibility);
        };
    }, []);


    const downloadInvoice = () => {
        const doc = new jsPDF();

        // Title (optional)
        doc.setFontSize(18);
        doc.setFont("helvetica", "bold");
        doc.text("User KYC Summary", 105, 10, { align: "center" });

        // USER DETAILS
        doc.setFontSize(14);
        doc.setTextColor(0, 102, 204);
        doc.text("User Details", 14, 20);

        doc.autoTable({
            headStyles: {
                fillColor: [0, 102, 204],
                textColor: [255, 255, 255],
                fontStyle: 'bold',
            },
            bodyStyles: {
                fillColor: [255, 255, 255],
                fontStyle: 'normal',
                fontSize: 10,
                textColor: [50, 50, 50],
            },
            alternateRowStyles: {
                fillColor: [255, 255, 255],
            },
            columnStyles: {
                0: { cellWidth: 95 },
                1: { cellWidth: 95 },
            },
            head: [['Field', 'Value']],
            body: verticalData.map(item => {
                if (item.field === 'Signature') return null; // skip image
                return [item.field, item.value || "--"];
            }).filter(Boolean),
            startY: 25,
        });

        // PHONE & ADDRESS
        const afterUserTable = doc.lastAutoTable.finalY + 10;
        doc.setTextColor(0, 102, 204);
        doc.text("Phone Numb. & Address", 14, afterUserTable);

        doc.autoTable({
            startY: afterUserTable + 5,
            head: [['Field', 'Value']],
            body: verticalData2.map(item => [item.field, item.value || "--"]),
            columnStyles: {
                0: { cellWidth: 95 },
                1: { cellWidth: 95 },
            },
            styles: {
                fontSize: 10,
                textColor: [50, 50, 50],
            },
            headStyles: {
                fillColor: [0, 102, 204],
                textColor: [255, 255, 255],
                fontStyle: 'bold',
            },
            bodyStyles: {
                fillColor: [255, 255, 255],
            },
            alternateRowStyles: {
                fillColor: [255, 255, 255],
            },
        });

        // KYC STATUS
        const afterAddressTable = doc.lastAutoTable.finalY + 10;
        doc.setTextColor(0, 102, 204);
        doc.text("KYC Status", 14, afterAddressTable);

        doc.autoTable({
            startY: afterAddressTable + 5,
            head: [['Field', 'Value']],
            body: verticalData3.map(item => {
                if (item.field === 'Signature') return null; // skip image
                return [item.field, item.value || "--"];
            }).filter(Boolean),
            columnStyles: {
                0: { cellWidth: 95 },
                1: { cellWidth: 95 },
            },
            styles: {
                fontSize: 10,
                textColor: [50, 50, 50],
            },
            headStyles: {
                fillColor: [0, 102, 204],
                textColor: [255, 255, 255],
                fontStyle: 'bold',
            },
            bodyStyles: {
                fillColor: [255, 255, 255],
            },
            alternateRowStyles: {
                fillColor: [255, 255, 255],
            },
        });

        // Footer with page number (just 1 page here)
        doc.setFontSize(10);
        doc.setTextColor(100);
        doc.text("Page 1 of 1", 105, 290, { align: 'center' });

        const userEmail = kycForm.user_email?.split("@")[0] || "user";
        doc.save(`${userEmail}-KycDocument-Form.pdf`);
    };



    return (
        <div className='App custom-individual'>
            <div className='container-fluid'>
                <div className='custom-analytic'>
                    <Modal show={showModal} onHide={handleClose} centered>
                        <Modal.Header closeButton>
                            <Modal.Title>Confirm Delete</Modal.Title>
                        </Modal.Header>
                        <Modal.Body>{content}</Modal.Body>
                        <Modal.Footer>
                            <Button variant="secondary" onClick={handleClose}>
                                Cancel
                            </Button>
                            <Button variant="danger" onClick={confirmDelete}>
                                Delete
                            </Button>
                        </Modal.Footer>
                    </Modal>
                    <div className='container'>
                        <div className='row'>
                            <div className='col-lg-2'>
                                <Dashboard />
                            </div>
                            <div className='col-lg-8 m-0 p-0'>
                                <div className="d-flex justify-content-between align-items-baseline">
                                    <div>
                                        <a href='/dashboard/user-list'>
                                            <p className="back-button text-dark"><FaRegArrowAltCircleLeft /> Back to User List</p>
                                        </a>
                                    </div>
                                    <div className="d-flex">
                                        <div className="me-3">
                                            <button className="custom-nav-button-1 active" onClick={downloadInvoice}>
                                                Download PDF
                                            </button>
                                        </div>
                                        {/* <button  className="custom-nav-button-1 active" onClick={(row) => { handleDeleteClick(row) }}>Delete <RiDeleteBin6Line /></button> */}
                                        <button className="custom-nav-button-1 active" onClick={(row) => { handleDeleteClick(row) }}>Delete <RiDeleteBin6Line /></button>

                                    </div>
                                </div>

                            </div>
                            <div className='col-lg-9 m-sm-auto m-0 p-0'>
                                <div className='liquidity-table-1 first-table-kyc'>
                                    <DataTable
                                        columns={columns}
                                        data={verticalData}
                                        noHeader
                                        highlightOnHover
                                        dense
                                    />
                                </div>
                                <div className='liquidity-table-1 mt-3 second-table-kyc'>
                                    <DataTable
                                        columns={columns1}
                                        data={verticalData2}
                                        noHeader
                                        highlightOnHover
                                        dense
                                    />
                                </div>
                                <div className='liquidity-table-1 mt-3 third-table-kyc'>
                                    <DataTable
                                        columns={columns2}
                                        data={verticalData3}
                                        noHeader
                                        highlightOnHover
                                        dense
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                    <div>
                        {isVisible && (
                            <button
                                onClick={scrollToTop}
                                style={{
                                    position: "fixed",
                                    bottom: "70px",
                                    right: "50px",
                                    padding: "5px 16px",
                                    fontSize: "25px",
                                    backgroundColor: "var(--color-1)",
                                    color: "var(--theme-text-1)",
                                    border: "none",
                                    borderRadius: "50%",
                                    cursor: "pointer",
                                }}
                            >
                                ↑
                            </button>
                        )}
                    </div>
                </div>

            </div>
        </div>
    );
}

export default KYCform;
